	if dir := os.Getenv("BERTH_USER_DIR"); dir != "" {
		if !filepath.IsAbs(dir) {
			return "", fmt.Errorf("BERTH_USER_DIR must be an absolute path")
		}
		return dir, nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".berth"), nil
